{
  "technical_and_design_decisions": [
    "Replace all internal copies of Hyperledger Fabric code with proper Go module dependencies on the official Fabric repositories.",
    "Pin to a specific version of the Fabric modules (e.g., v2.5.x) to ensure compatibility and avoid unexpected breaking changes.",
    "Update go.mod files to add required Fabric modules and remove any replace directives that pointed to local copies.",
    "Handle any modifications that were made to the copied code by adapting the SDK code to use the upstream API, potentially requiring minor code changes.",
    "Maintain backward compatibility where possible; document any breaking changes.",
    "For the temporary go.mod workaround (U6), implement a short-lived mechanism to respect chaincode package go.mod files during module transition, ensuring it is clearly marked as temporary.",
    "Run existing CI tests to validate changes; additional integration tests may be added for specific externalizations."
  ],
  "assumptions": [
    "The official Hyperledger Fabric Go modules (e.g., github.com/hyperledger/fabric) are published and accessible with stable APIs.",
    "The developer has full access to the fabric-sdk-go repository and its build system.",
    "All internal copies are exact copies or have minor modifications that can be resolved by using the upstream API directly.",
    "The effort estimates assume no major refactoring beyond import path changes and small code adjustments.",
    "The development environment is set up with Go 1.18+, module mode, and vendor directory is not used (or handled separately).",
    "The temporary go.mod workaround is simple and does not require deep changes to the build system.",
    "CI tests are comprehensive and passing after changes indicates success.",
    "Effort estimates are for the software development only, not including management overhead or release activities."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Initial analysis and planning",
      "activity_description": "Review all internal copies and third-party copies listed in user stories. Identify the upstream Fabric modules and packages to replace each copy. Determine import mapping and any modifications in the SDK code that need to be adapted. Plan the order of externalization to minimize conflicts.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A2",
      "activity_name": "Externalize gossip utilities (U1)",
      "activity_description": "Replace the internal copy of gossip utilities (protoutils) from internal/github.com/hyperledger/fabric/gossip with the official Fabric gossip module. Update all imports in the SDK, adjust any code that depended on modified behavior, and ensure compilation.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A3",
      "activity_name": "Externalize cauthdsl utilities (U2)",
      "activity_description": "Replace the third_party copy of cauthdsl from third_party/github.com/hyperledger/fabric/common/cauthdsl with the official Fabric common module. Update imports and fix any usage differences.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A4",
      "activity_name": "Externalize ccprovider structures (U3)",
      "activity_description": "Replace the third_party copy of ccprovider from third_party/github.com/hyperledger/fabric/core/common/ccprovider with the official Fabric core module. Update imports and adjust code as needed.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A5",
      "activity_name": "Externalize ledger structures (U4)",
      "activity_description": "Replace the third_party copy of ledger from third_party/github.com/hyperledger/fabric/core/ledger with the official Fabric ledger module. Update imports and handle any API differences.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A6",
      "activity_name": "Externalize common utilities (U5)",
      "activity_description": "Replace the internal copies under internal/github.com/hyperledger/fabric/common and internal/github.com/hyperledger/fabric/core with the official Fabric common and core modules. This involves many files and packages. Update imports throughout the SDK, resolve any modifications, and ensure the entire codebase compiles.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "A7",
      "activity_name": "Externalize configtxgen functions (U7)",
      "activity_description": "Replace the internal copy of configtxgen functions with the official Fabric configtxgen module. Update imports in the SDK and adjust any code that uses these functions (e.g., pkg/fab/resource/configtx.go).",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A8",
      "activity_name": "Externalize configtxlator functions (U8)",
      "activity_description": "Replace the internal copy of configtxlator functions with the official Fabric configtxlator module. Update imports and ensure compatibility.",
      "most_likely_effort": 1.5
    },
    {
      "activity_id": "A9",
      "activity_name": "Implement temporary go.mod honor workaround (U6)",
      "activity_description": "Design and implement a short-lived mechanism to honor go.mod files that are part of a chaincode package during the transition to Go modules. This involves parsing chaincode package go.mod and making it effective temporarily. Add appropriate warnings and documentation that it is temporary.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "A10",
      "activity_name": "Integration testing and debugging",
      "activity_description": "Run the full SDK test suite to ensure all externalizations and the go.mod workaround work together. Debug and fix any issues that arise from interdependencies or unexpected API changes. May include updating test mocks.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "A11",
      "activity_name": "Documentation updates",
      "activity_description": "Update SDK documentation (README, migration guide, release notes) to reflect the changes: removal of internal copies, new module dependencies, and the temporary go.mod workaround. Include instructions for developers on how to handle any breaking changes.",
      "most_likely_effort": 1.0
    },
    {
      "activity_id": "A12",
      "activity_name": "Code review and final adjustments",
      "activity_description": "Prepare code for review, address reviewer comments, make final adjustments, and ensure all changes are merged properly.",
      "most_likely_effort": 1.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 21.0
  }
}

